static inline std::vector<int64_t> GetDims(const gert::Shape* s) {
    std::vector<int64_t> v;
    for (size_t i = 0; i < s->GetOriginShape().GetDimNum(); ++i) {
        v.push_back(s->GetOriginShape().GetDim(i));
    }
    return v;
}
