namespace optiling {
const uint32_t BLOCK_DIM = 8;
const uint32_t TILE_NUM_N = 1; // 以 N'（B*D）为粒度分片

static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    Conv3dHardswishReluSoftmaxMeanCustomTiling tiling;

    // 输入 x: [B, C, D, H, W]
    const gert::Shape* x_shape = context->GetInputShape(0);
    auto dims = GetDims(x_shape);
    if (dims.size() != 5) {
        return ge::GRAPH_FAILED;
    }
    uint32_t B = static_cast<uint32_t>(dims[0]);
    uint32_t C = static_cast<uint32_t>(dims[1]);
    uint32_t D = static_cast<uint32_t>(dims[2]);
    uint32_t H = static_cast<uint32_t>(dims[3]);
    uint32_t W = static_cast<uint32_t>(dims[4]);

    // 属性
    int64_t group_attr = 1;
    (void)context->GetAttr("group", group_attr);
    float epsilon = 1e-5f;
    (void)context->GetAttr("epsilon", epsilon);

    // GroupNorm 以 [N', C, H, W] 形态进行（N' = B*D）
    uint32_t Np = B * D;

    // 生成 GroupNorm tiling（Host 侧）
    // 采用最大可用 Stack Buffer（示例中直接取最小上限）
    ge::Shape gnShape({static_cast<int64_t>(Np), static_cast<int64_t>(C),
                       static_cast<int64_t>(H), static_cast<int64_t>(W)});
    uint32_t maxSize = 0, minSize = 0;
    AscendC::GetGroupNormMaxMinTmpSize(gnShape, sizeof(float), false, static_cast<uint32_t>(group_attr), maxSize, minSize);
    uint32_t stackBufferSize = maxSize; // 简化取 maxSize，实际应结合 UB 空间选择

    AscendC::GetGroupNormNDTilingInfo(gnShape, stackBufferSize, sizeof(float), false, static_cast<uint32_t>(group_attr),
                                      tiling.groupNormTilingData);

    // 常规参数
    tiling.set_n(B);
    tiling.set_c(C);
    tiling.set_d(D);
    tiling.set_h(H);
    tiling.set_w(W);
    tiling.set_group(static_cast<uint32_t>(group_attr));
    tiling.set_epsilon(epsilon);
    tiling.set_tileNumN(TILE_NUM_N);
    uint32_t hwAlignSize = (sizeof(float) * H * W + 31) / 32 * 32 / sizeof(float);
    tiling.set_hwAlignSize(hwAlignSize);

    context->SetBlockDim(BLOCK_DIM);
    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());
    size_t *currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0;

    return ge::GRAPH_SUCCESS;
}
} // namespace optiling

